struct RollupConfig {
    uint256 proofSubmissionWindow;
    IERC20 feeAsset;
    IFeeJuicePortal feeAssetPortal;
    IRewardDistributor rewardDistributor;
    bytes32 vkTreeRoot;
    bytes32 protocolContractTreeRoot;
    IVerifier epochProofVerifier;
    IInbox inbox;
    IOutbox outbox;
    uint256 version;
}

